{
  "query": "/infographic an infographic of this month's payroll picture",
  "session_id": "{{sessionId}}",
  "output_mode": "a2ui"
}

{
  "query": "show worked hours by month as a chart",
  "session_id": "{{sessionId}}",
  "output_mode": "structured_chart"
}

{
  "query": "/widget pay code hours for month 2025-10",
  "session_id": "{{sessionId}}",
  "output_mode": "a2ui",
  "stream": true
}

{
  "kind": "dashboard",
  "title": "Demo Dashboard",
  "agent_id": "{{agentId}}",
  "session_id": "{{sessionId}}",
  "envelope": {
    "surfaceId": "demo-dashboard-infographic",
    "catalogId": "https://parrot.dev/catalogs/v1",
    "sendDataModel": false,
    "metadata": {
      "extensions": {
        "parrot_theme": "dark",
        "parrot_layout": "analytics"
      }
    },
    "components": [
      {
        "id": "root",
        "component": "Infographic",
        "title": "Demo Dashboard",
        "subtitle": "Two sections -> two tabs",
        "sections": [
          {
            "heading": "KPIs",
            "components": [
              {
                "component": "KPICard",
                "properties": {
                  "label": "Worked Hours",
                  "value": {
                    "path": "/hero/worked_hours"
                  },
                  "unit": "h",
                  "trend": "up"
                }
              },
              {
                "component": "KPICard",
                "properties": {
                  "label": "Payroll",
                  "value": {
                    "path": "/hero/payroll"
                  },
                  "unit": "USD",
                  "trend": "flat"
                }
              }
            ]
          },
          {
            "heading": "Trend",
            "components": [
              {
                "component": "FilterBar",
                "properties": {
                  "title": "Filters",
                  "filters": [
                    {
                      "column": "region",
                      "label": "Region",
                      "multiple": true,
                      "options": [
                        {
                          "label": "West",
                          "value": "West"
                        },
                        {
                          "label": "East",
                          "value": "East"
                        }
                      ]
                    }
                  ]
                }
              },
              {
                "component": "Chart",
                "properties": {
                  "title": "Hours by month",
                  "type": "line",
                  "x": "month",
                  "y": [
                    "hours"
                  ],
                  "showLegend": true,
                  "data": {
                    "path": "/series"
                  }
                }
              },
              {
                "component": "DataTable",
                "properties": {
                  "title": "Detail",
                  "columns": [
                    {
                      "name": "month",
                      "type": "string",
                      "title": "Month"
                    },
                    {
                      "name": "region",
                      "type": "string",
                      "title": "Region"
                    },
                    {
                      "name": "hours",
                      "type": "number",
                      "title": "Hours"
                    }
                  ],
                  "data": {
                    "path": "/series"
                  }
                }
              }
            ]
          }
        ]
      }
    ],
    "dataModel": {
      "hero": {
        "worked_hours": 18234.5,
        "payroll": 812345.0
      },
      "series": [
        {
          "month": "2025-07",
          "region": "West",
          "hours": 9100
        },
        {
          "month": "2025-07",
          "region": "East",
          "hours": 9134.5
        },
        {
          "month": "2025-08",
          "region": "West",
          "hours": 9600
        },
        {
          "month": "2025-08",
          "region": "East",
          "hours": 9411
        }
      ]
    }
  }
}

